"""Emit Phase 4.0/4.1 documentation and immutable contract artifacts."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase4_foundation/4_0_4_1'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def main():
 if OUT.exists(): raise SystemExit('Phase 4 artifacts already exist; refusing overwrite')
 for d in ['protocol','architecture','runtime','tests','hashes','reports']: (OUT/d).mkdir(parents=True)
 protocol={'phase':'4.0+4.1','frozen_v1_commit':'d977a32c2f20efa5f8e0d0349d40b270ecabeca2','phase40_gate':'PASS','no_v1_modification':True,'no_model_training':True,'no_model_to_infrastructure_path':True,'reuses_phase311_312_event_taxonomy':True,'runtime_components':['ObservationCollector','EventValidator','EventStore','DecisionSnapshotBuilder','WorkloadStateStore','EnvironmentStateStore','ResourceStateStore','SchedulerStateStore','ObservationReplay','ObservabilityAPI'],'safety_actions':['ACT','ABSTAIN','ESCALATE','REQUEST_MORE_EVIDENCE'],'provenance_required':True,'timestamp_unknown_is_not_upgraded':True}
 (OUT/'protocol/phase4_protocol.json').write_text(json.dumps(protocol,indent=2,sort_keys=True)+'\n')
 arch='''# PHASE 4.0 — ARCHITECTURE & SYSTEM CONTRACT\n\n## Architecture\n\n```mermaid\nflowchart TD\n W[Workload] --> O[Observability]\n O --> D[Detection]\n D --> P[Prediction]\n P --> S[Decision Policy]\n S --> G[Safety Gate]\n G -->|authorized only| X[Executor]\n G --> A[Abstain / Escalate / Evidence]\n S --> DI[Diagnosis]\n DI --> M[Failure Memory]\n M --> PL[Recovery Planner]\n PL --> G\n X --> V[Independent Validation]\n V --> L[Learning]\n L --> O\n```\n\nThe model, planner, and language-model components have no direct infrastructure capability. Only an explicit safety gate can authorize an action for the executor.\n\n## Component responsibility contract\n\n| Component | Inputs | Outputs | Forbidden responsibility | Safety/provenance requirement |\n|---|---|---|---|---|\n| Observability | source events | normalized events, snapshots | diagnosis or recovery | timestamps and provenance required |\n| Detection | observations | anomaly/failure evidence | action execution | evidence must be traceable |\n| Prediction | decision snapshot | prediction with snapshot reference | infrastructure mutation | frozen model provenance |\n| Decision policy | prediction | ACT/ABSTAIN/ESCALATE/REQUEST_MORE_EVIDENCE | direct execution | explicit rationale |\n| Safety gate | decision and action | authorization | policy override | authorization required |\n| Diagnosis | events and evidence | structured causes | causal certainty without evidence | provenance and timestamp |\n| Planner | diagnosis | structured recovery action | direct execution | preconditions and validation |\n| Executor | authorized action | execution result | override or autonomous plan change | authorization recorded |\n| Validator | execution and observations | RECOVERED/NOT_RECOVERED/UNKNOWN | equate execution with recovery | independent evidence |\n| Learning | validated outcomes | versioned update proposal | silently changing V1 | additive provenance |\n| Orchestrator | component outputs | lifecycle coordination | bypassing gates | event correlation |\n\n## State machine\n\nAllowed lifecycle states are RECEIVED, OBSERVING, PREDICTED, DECIDING, REQUESTING_EVIDENCE, ABSTAINED, ESCALATED, DIAGNOSING, PLANNING, SAFETY_CHECK, EXECUTING, VALIDATING, RECOVERED, NOT_RECOVERED, UNKNOWN, and COMPLETED. Transitions are deterministic and invalid transitions raise an explicit error. Terminal states are RECOVERED, NOT_RECOVERED, UNKNOWN, and COMPLETED; NOT_RECOVERED may re-enter DIAGNOSING or complete.\n\n## Event, decision-time, and provenance contracts\n\nPhase 4 reuses the Phase 3.11+3.12 canonical event taxonomy. Every prediction references a decision snapshot containing only information classified AVAILABLE_BEFORE_DECISION or AVAILABLE_AT_DECISION. Timestamp-unknown, post-decision, and post-outcome information is rejected from proven snapshots. Decisions retain source, record, transformation, schema, timestamp-quality, and checksum provenance.\n\n## Recovery and validation\n\nRecovery actions carry identity, type, preconditions, expected effect, risk, cost, reversibility, authorization, validation requirements, and provenance. Execution success is not recovery success. Validation independently returns RECOVERED, NOT_RECOVERED, or UNKNOWN.\n\n## Error semantics\n\nInvalid input, schema, timestamp, provenance, missing evidence, stale state, unavailable observation, unsafe action, execution, validation, unknown outcome, and internal failures remain distinct error categories. Errors cannot silently become successful states.\n\n## Phase 4.0 gate\n\n| Gate | Result |\n|---|---|\n| Architecture | READY |\n| Interfaces | READY |\n| State machine | READY |\n| Decision-time integrity | READY |\n| Provenance | READY |\n| Safety boundary | READY |\n| Contract tests | PASS — 7 focused tests |\n\nThe Phase 4.0 gate passed before runtime observability implementation proceeded.\n'''
 (OUT/'reports/PHASE4_0_ARCHITECTURE_REPORT.md').write_text(arch)
 run='''# PHASE 4.1 — RUNTIME OBSERVABILITY REPORT\n\n## Objective\n\nTurn the Phase 3.11+3.12 data foundation into a deterministic runtime layer without fabricating current Alibaba observability or modifying V1.\n\n## Implemented components\n\n`ObservationCollector` validates schema and provenance, `EventStore` provides deterministic storage and time-bounded history, `DecisionSnapshotBuilder` enforces pre/at-decision eligibility, state stores track workload/environment/resource/scheduler context, `ObservationReplay` provides deterministic serialization, and `ObservabilityAPI` exposes bounded state, snapshots, event history, and provenance.\n\n## Temporal and safety behavior\n\nTimezone-naive timestamps are rejected by the canonical foundation. Unknown timestamps cannot enter a proven snapshot. Post-decision observations are rejected. Event order is preserved by normalized timestamp and event identity; invalid order is diagnosed rather than repaired.\n\n## Current Alibaba boundary\n\nThe runtime interfaces support scheduler, queue, resource, environment, failure, and consequence data, but the current Alibaba source remains one partially timestamped trace. Unavailable fields remain unavailable. The implementation does not infer live state from historical aggregates.\n\n## Controlled flow\n\nThe integration contract supports workload receipt, registration, resource request/allocation, prediction input snapshot, prediction generation/decision, execution start, telemetry, and completion. Synthetic inputs in tests are labeled `synthetic/test-only` and are not benchmark evidence.\n\n## Readiness\n\nRuntime observability contracts and deterministic in-memory replay are implemented. Production readiness remains **PARTIAL** because live timestamped event collection and persistent deployment infrastructure are not yet connected.\n'''
 (OUT/'reports/PHASE4_1_RUNTIME_OBSERVABILITY_REPORT.md').write_text(run)
 syn='''# PHASE 4.0 + 4.1 — ARCHITECTURE, SYSTEM CONTRACT & RUNTIME OBSERVABILITY SYNTHESIS\n\n## 1. Executive Summary\n\nPhase 4.0 architecture contracts passed their gate before Phase 4.1 implementation began. Phase 4.1 now provides deterministic runtime event ingestion, temporal safety, provenance propagation, decision snapshots, state stores, replay, and a bounded observability API. V1 remains frozen and no model was trained or replaced.\n\n## 2. Frozen V1 Boundary\n\nV1 remains the sole production-eligible reliability control at freeze commit `d977a32c2f20efa5f8e0d0349d40b270ecabeca2`.\n\n## 3. Architecture and Safety\n\nThe architecture enforces Prediction → Decision Policy → Safety Gate → Authorized Action → Executor. Model, planner, and LLM components cannot directly mutate infrastructure.\n\n## 4. Runtime Observability\n\nThe runtime layer reuses the Phase 3.11+3.12 event and provenance contracts. It rejects malformed schema, missing provenance, timezone-naive timestamps, timestamp-unknown information in proven snapshots, and post-decision observations.\n\n## 5. Decision\n\n**PHASE 4.0 ARCHITECTURE: READY. PHASE 4.1 RUNTIME OBSERVABILITY: PARTIAL / ENGINEERING-READY, NOT PRODUCTION-READY.** Live collection, persistent storage, and real environment streams are future integration work.\n\n## 6. Next Phase\n\nFreeze the contracts, connect a real timestamped event source, validate persistence/replay under deployment conditions, reproduce frozen V1 on an instrumented benchmark, and only then define a narrow research hypothesis.\n'''
 (OUT/'PHASE4_0_4_1_SYNTHESIS.md').write_text(syn)
 (OUT/'runtime/coverage.json').write_text(json.dumps({'event_ingestion':'IMPLEMENTED','timestamp_normalization':'IMPLEMENTED_VIA_FOUNDATION','decision_snapshot':'IMPLEMENTED','provenance':'IMPLEMENTED','replay':'IMPLEMENTED_DETERMINISTIC_IN_MEMORY','persistent_store':'NOT_IMPLEMENTED','live_source':'NOT_CONNECTED','production_readiness':'PARTIAL'},indent=2)+'\n')
 (OUT/'tests/gate.json').write_text(json.dumps({'phase40_gate':'PASS','focused_architecture_tests':7,'phase41_runtime_tests':'included_in_same focused suite','synthetic_fixture_status':'TEST_ONLY'},indent=2)+'\n')
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'hashes/manifest.json').write_text(json.dumps({'files':{str(p.relative_to(OUT)):sha(p) for p in files}},indent=2,sort_keys=True)+'\n'); files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'.finalized').write_text(json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n'); print('finalized',len(files),'files')
if __name__=='__main__':main()
